<?php
declare(strict_types=1);
require_once __DIR__.'/../src/functions.php';
$version='1.0.1';$today=date('d.m.Y');$employees=[];$dataError='';
try{$employees=loadEmployees(__DIR__.'/../dataset/employees.csv');}catch(Throwable $x){$dataError=$x->getMessage();}
$cases=[];try{$cases=loadFormCases(__DIR__.'/../dataset/form_cases.json');}catch(Throwable $x){$dataError=$dataError?:$x->getMessage();}
$values=['name'=>'','email'=>'','department'=>'','experience'=>''];$errors=[];$success=false;
if($_SERVER['REQUEST_METHOD']==='POST'){$r=validateInput($_POST);$values=$r['values'];$errors=$r['errors'];if(!$errors){$id=$employees?max(array_column($employees,'id'))+1:1;$employees[]=['id'=>$id,'name'=>$values['name'],'department'=>$values['department'],'experience'=>(int)$values['experience'],'email'=>$values['email']];$success=true;$values=['name'=>'','email'=>'','department'=>'','experience'=>''];}}
$departments=array_values(array_unique(array_column($employees,'department')));sort($departments,SORT_NATURAL|SORT_FLAG_CASE);$filter=trim((string)($_GET['department']??''));$visible=$filter===''?$employees:array_values(array_filter($employees,fn($x)=>lowerUtf8($x['department'])===lowerUtf8($filter)));
?><!doctype html><html lang="ru"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Учёт сотрудников — ТРПО 04</title><link rel="stylesheet" href="/assets/styles.css"></head><body>
<header class="site-header"><div class="brand">TRPO / Практическая №04</div><div class="tag">PHP · CSV · GET / POST</div></header><nav class="site-nav"><a href="#overview">Обзор</a><a href="#form">Добавление</a><a href="#employees">Сотрудники</a><a href="#cases">Контрольные кейсы</a></nav>
<main class="wrap"><section class="hero" id="overview"><div class="eyebrow">Технологии разработки программного обеспечения</div><h1>Учёт сотрудников</h1><p class="muted">Форма добавления сотрудников, серверная проверка данных и фильтрация таблицы по отделу.</p><strong>Солопов Антон · ЭПБО-01-25</strong><p><span class="pill">Версия <?=e($version)?></span> <span class="muted">Дата выполнения: <?=e($today)?></span></p></section>
<?php if($dataError):?><div class="notice error"><?=e($dataError)?></div><?php endif;?>
<div class="cards"><article class="card"><div class="muted">Сотрудников</div><div class="metric"><?=count($visible)?></div></article><article class="card"><div class="muted">Отделов</div><div class="metric"><?=count($departments)?></div></article><article class="card"><div class="muted">Проверочных кейсов</div><div class="metric"><?=count($cases)?></div></article></div>
<section class="panel" id="form"><div class="eyebrow">POST · Серверная валидация</div><h2>Добавить сотрудника</h2><?php if($success):?><div class="notice success">Данные проверены. Запись добавлена в список текущего ответа; исходный CSV не изменяется.</div><?php endif;?><?php if($errors):?><div class="notice error">Исправьте отмеченные поля. Введённые значения сохранены.</div><?php endif;?>
<form method="post" class="form-grid" novalidate><?php foreach(['name'=>'ФИО','email'=>'Email','department'=>'Отдел','experience'=>'Стаж, лет'] as $k=>$label):?><div class="field"><label for="<?=$k?>"><?=e($label)?></label><input id="<?=$k?>" name="<?=$k?>" value="<?=e($values[$k])?>" <?=$k==='email'?'type="email"':($k==='experience'?'type="number" min="0" max="60"':'type="text')?> required><?php if(isset($errors[$k])):?><span class="error-text"><?=e($errors[$k])?></span><?php endif;?></div><?php endforeach;?><div><button>Проверить и добавить</button></div></form></section>
<section class="panel" id="employees"><div class="eyebrow">GET · Фильтрация</div><h2>Список сотрудников</h2><form method="get" class="form-grid"><div class="field"><label for="department">Отдел</label><select id="department" name="department"><option value="">Все отделы</option><?php foreach($departments as $d):?><option value="<?=e($d)?>" <?=$filter===$d?'selected':''?>><?=e($d)?></option><?php endforeach;?></select></div><div><button>Применить</button> <a class="btn ghost" href="/">Сбросить</a></div></form><p class="muted">Показано записей: <?=count($visible)?></p><div class="table-wrap"><table class="table"><thead><tr><th>ID</th><th>ФИО</th><th>Отдел</th><th>Стаж</th><th>Email</th></tr></thead><tbody><?php foreach($visible as $x):?><tr><td><?=(int)$x['id']?></td><td><?=e($x['name'])?></td><td><?=e($x['department'])?></td><td><?=(int)$x['experience']?></td><td><?=e($x['email'])?></td></tr><?php endforeach;?></tbody></table></div><?php if(!$visible):?><div class="empty">Сотрудники не найдены.</div><?php endif;?></section>
<section class="panel" id="cases"><div class="eyebrow">Dataset · form_cases.json</div><h2>Контрольные сценарии</h2><div class="table-wrap"><table class="table"><thead><tr><th>Сценарий</th><th>Ожидание</th><th>Результат</th></tr></thead><tbody><?php foreach($cases as $c):$r=validateInput(['name'=>$c['name']??'','email'=>'case@example.test','department'=>'Тест','experience'=>(string)($c['experience']??'')]);$actual=$r['errors']===[];$expected=(bool)($c['valid']??false);?><tr><td><?=e($c['case']??'Без названия')?></td><td><?=$expected?'Корректно':'Ошибка'?></td><td><span class="pill"><?=$actual===$expected?'Совпадает':'Не совпадает'?></span></td></tr><?php endforeach;?></tbody></table></div></section></main><footer class="site-footer">Практическая работа №04 · PHP</footer></body></html>
